import type { IconManifest } from "../../src/types/icon-manifest.js";

/** Matches `formatter.lineWidth` in biome.json; tests prove Biome leaves the output unchanged. */
const lineWidth = 100;

const header = [
  "// Generated by @qeetrix/icons from icons/. Do not edit this file directly.",
  "// Run `bun run generate` to update it.",
  "",
];

export type BarrelExport = {
  readonly id: string;
  readonly componentName: string;
};

/**
 * The generated root barrel: one static re-export per icon, in codepoint order of public id.
 * No registry, no manifest import, no side effects. With zero icons it is an empty module.
 * Biome never wraps a single-specifier export, however long.
 */
export function renderBarrel(exports: readonly BarrelExport[]): string {
  const lines = exports.map(
    ({ id, componentName }) =>
      `export { ${componentName} } from ${JSON.stringify(`./icons/${id}.js`)};`,
  );
  return [...header, ...(lines.length > 0 ? lines : ["export {};"]), ""].join("\n");
}

/** A manifest value: strings quoted, the short `variants` list kept on one line as Biome does. */
function value(entry: unknown): string {
  return Array.isArray(entry)
    ? `[${entry.map((item) => JSON.stringify(item)).join(", ")}]`
    : JSON.stringify(entry);
}

/**
 * One manifest property, as Biome prints it: a line that is too long breaks after the colon,
 * except after a key shorter than indent width plus three, where Biome never breaks.
 */
function property(key: string, value: string): string {
  const flat = `      ${key}: ${value},`;
  return flat.length <= lineWidth || key.length < 5 ? flat : `      ${key}:\n        ${value},`;
}

/**
 * The typed manifest module behind `@qeetrix/icons/manifest`. Each entry is printed expanded,
 * which Biome preserves, so a one-icon change is a small, readable diff.
 */
export function renderManifestModule(manifest: IconManifest): string {
  const entries = manifest.icons.map((entry) =>
    [
      "    {",
      ...Object.entries(entry).map(([key, field]) => property(key, value(field))),
      "    },",
    ].join("\n"),
  );
  return [
    ...header,
    'import type { IconManifest } from "../types/icon-manifest.js";',
    "",
    "export const iconManifest: IconManifest = {",
    `  schemaVersion: ${manifest.schemaVersion},`,
    ...(entries.length > 0 ? ["  icons: [", ...entries, "  ],"] : ["  icons: [],"]),
    "};",
    "",
  ].join("\n");
}

/**
 * `icon-manifest.json`: the same data for repository and non-JavaScript tooling, printed like the
 * module (entries expanded, `variants` inline) so Biome leaves it unchanged.
 */
export function renderManifestJson(manifest: IconManifest): string {
  const entries = manifest.icons.map((entry) =>
    [
      "    {",
      Object.entries(entry)
        .map(([key, field]) => `      ${JSON.stringify(key)}: ${value(field)}`)
        .join(",\n"),
      "    }",
    ].join("\n"),
  );
  return [
    "{",
    `  "schemaVersion": ${manifest.schemaVersion},`,
    ...(entries.length > 0 ? ['  "icons": [', entries.join(",\n"), "  ]"] : ['  "icons": []']),
    "}",
    "",
  ].join("\n");
}
